import { containerModifiersAttr } from "../../dxp/_utils/component.helper";

export default {
    title: 'CSS Components/Layout',
     parameters: {
        layout: 'fullscreen',
    },
};

const modAttrAltBg = containerModifiersAttr({containerModifiers: { variant: 'alt-background'}});
const modAttrSpacious = containerModifiersAttr({containerModifiers: { verticalSpace: 'spacious'}});
